import { _decorator, Component, Node } from 'cc';
import { mEmitter } from '../mEmitter';
import { EmitterEventType } from '../constants';
const { ccclass, property } = _decorator;

@ccclass('PopupManager')
export class PopupManager extends Component{

    @property(Node)
    background: Node = null;
    @property(Node)
    settingPopup: Node = null;
    @property(Node)
    resultPopup: Node = null;

    protected onLoad(): void {
        this.settingPopup.active = false;
        this.resultPopup.active = false;
    }

    protected onEnable(): void {
        mEmitter.instance.registerEvent(EmitterEventType.POPUP.SETTING, this.showSettingPopup.bind(this), this.node)
    }

    showSettingPopup() {
        this.settingPopup.active = true;
    }



}

